package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.printing.*;import com.intermarche.backoffice.engine.printing.*;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import jakarta.inject.Inject;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(PrintingWorkflowTest.class)
class PrintingWorkflowTest extends ParcelWorkflowTest {
 @Inject PrintQueue queue;
 Map<String,Object> post(String actor,String path,Map<String,Object> body){return given().auth().oauth2(actor).contentType("application/json").body(body).post("/printing"+path).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> printer(String simulation){return post(f.manager(),"/printers",Map.of("storeId",f.store(),"requestKey",key(),"code","P-"+key().substring(0,8),"label","Imprimante test","transport","SIMULATOR","simulation",simulation));}
 @Test void aFreePhysicalToteCanBePrintedWithoutCreatingAUsageOrStock(){
  long id=QuarkusTransaction.requiringNew().call(()->{var t=new com.intermarche.backoffice.domain.store.Tote();t.store=com.intermarche.backoffice.domain.store.Store.findById(f.store());t.code="PRINT-FREE";t.toteType=com.intermarche.backoffice.domain.store.Tote.ToteType.STANDARD;t.volume=new java.math.BigDecimal("40");t.persistAndFlush();return t.id;});
  var p=printer("SUCCESS");var job=post(f.picker(),"/jobs",Map.of("storeId",f.store(),"requestKey",key(),"printerId",p.get("id"),"subjectType","PHYSICAL_TOTE","subjectId",id));assertEquals("PRINT-FREE",job.get("code"));
  given().auth().oauth2(f.picker()).get("/printing/subjects/PHYSICAL_TOTE/"+id+"/last-job?storeId="+f.store()).then().statusCode(200);
  QuarkusTransaction.requiringNew().run(()->assertEquals(0,com.intermarche.backoffice.domain.executing.LoadedTote.count("tote.id",id)));
 }
 @Test void jobHasImmutableIdentityAndReprintingNeverChangesStock(){var parcel=prepared();var printer=printer("SUCCESS");var input=Map.<String,Object>of("storeId",f.store(),"requestKey",key(),"printerId",printer.get("id"),"subjectType","PARCEL","subjectId",parcel.get("id"));var job=post(f.picker(),"/jobs",input);var replay=post(f.picker(),"/jobs",input);assertEquals(job.get("id"),replay.get("id"));long id=((Number)job.get("id")).longValue();QuarkusTransaction.requiringNew().run(()->{var j=PrintJob.<PrintJob>findById(id);j.state="SENT";});var copy=post(f.picker(),"/jobs",Map.of("storeId",f.store(),"requestKey",key(),"printerId",printer.get("id"),"jobId",id,"reason","Étiquette abîmée"));assertNotEquals(job.get("id"),copy.get("id"));assertEquals(job.get("code"),copy.get("code"));assertEquals(job.get("payloadSha256"),copy.get("payloadSha256"));assertEquals(id,((Number)copy.get("reprintOf")).longValue());QuarkusTransaction.requiringNew().run(()->eq(20,stocks.availability(physical.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical));given().auth().oauth2(f.picker()).contentType("application/json").body(Map.of("storeId",f.store(),"requestKey",key(),"code","P","label","Interdit")).post("/printing/printers").then().statusCode(403);}
 @Test void interruptedSendingBecomesUnknownAndIsNeverAutomaticallyResent(){var parcel=prepared();var p=printer("SUCCESS");var job=post(f.picker(),"/jobs",Map.of("storeId",f.store(),"requestKey",key(),"printerId",p.get("id"),"subjectType","PARCEL","subjectId",parcel.get("id")));long id=((Number)job.get("id")).longValue();QuarkusTransaction.requiringNew().run(()->{var j=PrintJob.<PrintJob>findById(id);j.state="SENDING";j.sendingAt=com.intermarche.backoffice.domain.util.DateTimeProvider.now().minusMinutes(3);j.attemptCount=1;var a=new PrintAttempt();a.job=j;a.attemptNumber=1;a.state="SENDING";a.startedAt=j.sendingAt;a.persist();});queue.claim();QuarkusTransaction.requiringNew().run(()->{var j=PrintJob.<PrintJob>findById(id);assertEquals("UNKNOWN",j.state);assertEquals(1,j.attemptCount);assertEquals("UNKNOWN",PrintAttempt.<PrintAttempt>find("job",j).firstResult().state);});given().auth().oauth2(f.picker()).get("/printing/jobs/"+id+"?storeId="+f.other()).then().statusCode(403);}
}
